            array('id' => '63','theme_id'=>'1','page_name' => 'Terms of use','link_key' => 'terms-hero-section','hints' => 'Terms Hero Section','title' => 'Terms of Use','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => NULL,'description_label' => NULL,'image' => 'upload/website-content/27021220240325050005.jpg','image_label' => NULL,'created_at' => '2024-03-25 05:00:06','updated_at' => '2024-03-25 05:00:06'),
            array('id' => '64','theme_id'=>'1','page_name' => 'Terms of use','link_key' => 'terms-content-section','hints' => 'Terms Content Section','title' => 'Terms and Conditions','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>The Department of Immigration and Passport Online Visa Services website is maintained for your personal user and viewing. Access and use by you of this site constitutes acceptance by you of these terms and conditions which take effect from the date of first use.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:04:16','updated_at' => '2024-03-25 05:04:16'),
            array('id' => '65','theme_id'=>'1','page_name' => 'Terms of use','link_key' => 'terms-content-section','hints' => 'Terms Content Section','title' => 'Copyright','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>This page contains information on copyright and what you should do if you want to link to our website or user our news feeds.</p>

            <p>The material featured on this website is subject to copyright protection unless otherwise indicated. The material may be downloaded to file or printer for the purposes of research and private study. Any other proposed use of the material is subject to a copyright license.</p>

            <p>The permission to reproduce protected material does not extend to any material on this website, which is identified as being the copyright of a third party. Authorization to reproduce such material must be obtained from the copyright holders concerned.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:04:51','updated_at' => '2024-03-25 05:04:51'),
            array('id' => '66','theme_id'=>'1','page_name' => 'Terms of use','link_key' => 'terms-content-section','hints' => 'Terms Content Section','title' => 'Linking to our website','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>We welcome and encourage other website&#39;s to link to the international group: Visa Services website. You do not have to ask permission to link to our website (use of our logo is by permission). However, you must comply with the conditions below:</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:05:30','updated_at' => '2024-03-25 05:05:30'),
            array('id' => '67','theme_id'=>'1','page_name' => 'Terms of use','link_key' => 'terms-content-section','hints' => 'Terms Content Section','title' => 'Links to third party websites','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>If you send an email or letter to the Department of Immigration and Passport asking for information, we may need to contact other government departments to find that information. If your question is technical, we may need to pass it to our technology suppliers. We do not pass on any of your personal information when dealing with your enquiry, unless you have given us permission to do so. Once we have replied to you, we keep a record of your messages for up to six months for reference and audit purposes. After this time, it should be deleted.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:06:09','updated_at' => '2024-03-25 05:06:09'),
            array('id' => '68','theme_id'=>'1','page_name' => 'Terms of use','link_key' => 'terms-content-section','hints' => 'Terms Content Section','title' => 'Disclaimer','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>The information available on this site is not intended to be comprehensive and many details which are relevant to particular circumstances may have been omitted. It is not a complete statement of immigration and nationality law or policy.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:06:41','updated_at' => '2024-03-25 05:06:41'),
            array('id' => '70','theme_id'=>'1','page_name' => 'Privacy Policy','link_key' => 'privacy-hero-section','hints' => 'Privacy Hero Section','title' => 'Privacy and Policy','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => NULL,'description_label' => NULL,'image' => 'upload/website-content/13607520240325051412.jpg','image_label' => NULL,'created_at' => '2024-03-25 05:14:12','updated_at' => '2024-03-25 05:14:12'),
            array('id' => '71','theme_id'=>'1','page_name' => 'Privacy Policy','link_key' => 'privacy-content-section','hints' => 'Privacy Content Section','title' => 'Privacy and Policy','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>The Home Office reserves the right to gather information relating to site usage. Any information gathered is primarily for internal use to allow us to refine and improve our customer service. Where disclosure of information to a third party is likely we will, where possible, try to ensure that this is clearly indicated. This does not affect your statutory rights.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:17:09','updated_at' => '2024-03-25 05:17:09'),
            array('id' => '72','theme_id'=>'1','page_name' => 'Privacy Policy','link_key' => 'privacy-content-section','hints' => 'Privacy Content Section','title' => 'Online visa applications - What information do we collect?','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>We collect all the personal information you complete on the visa application electronic forms.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:17:34','updated_at' => '2024-03-25 05:17:34'),
            array('id' => '73','theme_id'=>'1','page_name' => 'Privacy Policy','link_key' => 'privacy-content-section','hints' => 'Privacy Content Section','title' => 'Links to external sites','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>Our website contains links to our websites, both of those government departments and of other organizations. This privacy policy applies only to our site, so you should always be aware when you are moving to another site. Please read the privacy statement of any site which collects personal information.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:18:16','updated_at' => '2024-03-25 05:18:16'),
            array('id' => '74','theme_id'=>'1','page_name' => 'Privacy Policy','link_key' => 'privacy-content-section','hints' => 'Privacy Content Section','title' => 'Your queries','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>If you send an email or letter to the Department of Immigration and Passport asking for information, we may need to contact other government departments to find that information. If your question is technical, we may need to pass it to our technology suppliers. We do not pass on any of your personal information when dealing with your enquiry, unless you have given us permission to do so. Once we have replied to you, we keep a record of your messages for up to six months for reference and audit purposes. After this time, it should be deleted.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:18:51','updated_at' => '2024-03-25 05:18:51'),
            array('id' => '75','theme_id'=>'1','page_name' => 'Privacy Policy','link_key' => 'privacy-content-section','hints' => 'Privacy Content Section','title' => 'Changes to this privacy policy','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>If this privacy policy changes in any way, we will place an updated version on this page. Regularly reviewing this page ensures you are always aware of what information we collect, how we use it and under what circumstances, if any, we will share it with other parties.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:19:23','updated_at' => '2024-03-25 05:19:23'),
            array('id' => '77','theme_id'=>'1','page_name' => 'Cookie Policy','link_key' => 'cookie-hero-section','hints' => 'Cookie Hero Section','title' => 'Cookie Policy','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => NULL,'description_label' => NULL,'image' => 'upload/website-content/87310720240325052335.jpg','image_label' => NULL,'created_at' => '2024-03-25 05:23:35','updated_at' => '2024-03-25 05:23:35'),
            array('id' => '78','theme_id'=>'1','page_name' => 'Cookie Policy','link_key' => 'cookie-content-section','hints' => 'Cookie Content Section','title' => 'What are cookies?','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>Cookies are files or pieces of information that may be stored on system or internet enabled devices of the User, when the User visits the website/s of VFS Global. VFS Global uses cookies to make the website/s simpler to use and to create more valuable experiences for you as user. VFS Global cannot identify the User personally from this information. Cookies in themselves do not identify the individual user, just the computer or mobile device you are using via a randomly generated identifying tag.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:25:49','updated_at' => '2024-03-25 05:25:49'),
            array('id' => '79','theme_id'=>'1','page_name' => 'Cookie Policy','link_key' => 'cookie-content-section','hints' => 'Cookie Content Section','title' => 'How VFS use cookies?','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>We collect all the personal information you complete on the visa application electronic forms.</p>

            <p>Our Site may use and allow third parties to place cookies (session and persistent), pixels/tags, SDKs, application program interfaces (&quot;APIs&quot;), and other technologies (collectively, &quot;Cookies&quot;) on our Site that may collect and store certain information about you. Some of these Cookies are necessary to provide, secure, and maintain the basic functions of the Site</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:26:22','updated_at' => '2024-03-25 05:26:22'),
            array('id' => '80','theme_id'=>'1','page_name' => 'Cookie Policy','link_key' => 'cookie-content-section','hints' => 'Cookie Content Section','title' => 'EU/UK Site Visitors','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>Our website contains links to our websites, both of those government departments and of other organizations. This privacy policy applies only to our site, so you should always be aware when you are moving to another site. Please read the privacy statement of any site which collects personal information.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:26:46','updated_at' => '2024-03-25 05:26:46'),
            array('id' => '81','theme_id'=>'1','page_name' => 'Cookie Policy','link_key' => 'cookie-content-section','hints' => 'Cookie Content Section','title' => 'How to manage or opt out of Cookies from VFS Global?','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>If you send an email or letter to the Department of Immigration and Passport asking for information, we may need to contact other government departments to find that information. If your question is technical, we may need to pass it to our technology suppliers. We do not pass on any of your personal information when dealing with your enquiry, unless you have given us permission to do so. Once we have replied to you, we keep a record of your messages for up to six months for reference and audit purposes. After this time, it should be deleted.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:27:10','updated_at' => '2024-03-25 05:27:10'),
            array('id' => '82','theme_id'=>'1','page_name' => 'Cookie Policy','link_key' => 'cookie-content-section','hints' => 'Cookie Content Section','title' => 'Changes to this privacy policy','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>If this privacy policy changes in any way, we will place an updated version on this page. Regularly reviewing this page ensures you are always aware of what information we collect, how we use it and under what circumstances, if any, we will share it with other parties.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 05:30:02','updated_at' => '2024-03-25 05:30:02'),
            array('id' => '84','theme_id'=>'1','page_name' => 'Help Center','link_key' => 'help-hero-section','hints' => 'Help Hero Section','title' => 'Need help? We\'re here for you!','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => NULL,'description_label' => NULL,'image' => 'upload/website-content/92805520240325061925.jpg','image_label' => NULL,'created_at' => '2024-03-25 06:19:25','updated_at' => '2024-03-25 06:19:25'),
            array('id' => '85','theme_id'=>'1','page_name' => 'Help Center','link_key' => 'help-booking-section','hints' => 'Help booking Section','title' => 'How can I get more information about the room or property\'s facility?','title_label' => NULL,'subtitle' => NULL,'subtitle_label' => NULL,'button_text' => NULL,'button_text_label' => NULL,'button_link' => NULL,'button_link_label' => NULL,'description' => '<p>You can find details about the property in your confirmation email or on the property detail page. For anything else, you can also contact property directly.</p>','description_label' => NULL,'image' => NULL,'image_label' => NULL,'created_at' => '2024-03-25 06:28:03','updated_at' => '2024-03-25 06:28:03'),
